                '/^\d{12}$/',
                // 12-digit domestic.
                '/^\d{10}$/',
                // 10-digit legacy.
                '/^\d{9}$/',
                // 9-digit legacy.
                '/^\d{8}$/',
                // 8-digit calling card/legacy.
                // Service-specific patterns.
                '/^XP\d{9}CA$/',
                // Xpresspost International.
                '/^EX\d{9}CA$/',
                // Express International.
                '/^PR\d{9}CA$/',
                // Priority.
                '/^RG\d{9}CA$/',
                // Regular (deprecated, legacy).
                '/^RM\d{9}CA$/',
                // Registered Mail.
                '/^CM\d{9}CA$/',
                // Certified Mail.
                '/^[A-Z]{2}\d{7}[A-Z]{2}$/',
                // International format: XX#######XX.
                '/^[A-Z]{1}\d{9}[A-Z]{1}$/',
                // Domestic formats: X#########X.
                '/^FD\d{10,12}$/',
                // FlexDelivery.
                '/^PO\d{10,12}$/',
                // Post Office Box service.
                '/^CP\d{10,14}$/',
                // Canada Post business.
                '/^SM\d{10,14}$/',
                // Small packet.
                // Legacy and alternative formats.
                '/^[0-9]{13}[A-Z]{1}$/',
            ),
            'confidence' => 92,
