    /**
     * ShopifyFetcher class.
     *
     * This class is responsible for fetching data from the Shopify platform.
     * Uses ShopifyClient for REST API communication and will be extended with
     * GraphQL API logic in future PRs.
     */
    class ShopifyFetcher implements \Automattic\WooCommerce\Internal\CLI\Migrator\Interfaces\PlatformFetcherInterface
    {
        /**
         * Comprehensive GraphQL query for fetching Shopify products.
         *
         * This query fetches all necessary product data including variants, images,
         * collections, and metadata for migration to WooCommerce.
         */
        const SHOPIFY_PRODUCT_QUERY = <<<'GRAPHQL'
        query GetShopifyProducts(
        	$first: Int!,
        	$after: String,
        	$query: String,
        	$variantsFirst: Int = 100
        ) {
        	products(first: $first, after: $after, query: $query) {
        		edges {
        			cursor
        			node {
        				id
        				title
        				handle
        				descriptionHtml
        				status
        				createdAt
        				vendor
        				tags
        				onlineStoreUrl
        				options(first: 10) {
        					id
        					name
        					position
        					values
        				}
        				featuredMedia {
        					... on MediaImage {
        						id
        						image {
        							url
        							altText
        						}
        					}
        				}
        				media(first: 50) {
        					edges {
        						node {
        							... on MediaImage {
        								id
        								image {
        									url
        									altText
        								}
        							}
        						}
        					}
        				}
        				variants(first: $variantsFirst) {
        					edges {
        						node {
        							id
        							product { id }
        							price
        							compareAtPrice
        							sku
        							taxable
        							inventoryPolicy
        							inventoryQuantity
        							position
        							inventoryItem {
        								tracked
        								unitCost {
        									amount
        									currencyCode
        								}
        								measurement {
        									weight {
        										value
        										unit
        									}
        								}
        							}
        							media(first: 1) {
        								edges {
        									node {
        										... on MediaImage {
        											id
        											image {
        												url
        												altText
        											}
        										}
        									}
        								}
